/**
 * Подтема SddsFinAiTheme.OnLight
 */
@Composable
public fun SddsFinAiTheme.OnLight(
    isDark: Boolean = isSystemInDarkTheme(),
    content: @Composable
    () -> Unit,
) {
    val currentColors = LocalSddsFinAiColors.current
    val overrideColors = currentColors.copyAttrs(OnLightColorsOverride)
    val currentGradients = LocalSddsFinAiGradients.current
    val overrideGradients = currentGradients.copyAttrs(OnLightGradientsOverride)
    SddsFinAiTheme(
        colors = overrideColors,
        gradients = overrideGradients,
        content = content,
    )
}
